INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0ed-76a8-b98d-3f0ba732ac5c'::uuid, '019f9df7-a2a2-78fc-bd9e-a40e9b4f9363'::uuid, 'The Great Pyramid has surface area 8.30 × 10^4 m^2 and volume 2.45 × 10^4 m^3. A similar replica has volume 9.22 × 10^-6 m^3. Estimate the surface area of the replica.', '4.33 × 10^-2 m^2', 'For similar solids, surface area scales with the square of the linear scale and volume scales with the cube. Use the volume ratio to find the linear scale, then square it and apply it to 8.30 × 10^4. This gives approximately 4.33 × 10^-2 m^2.', 'Hard', '{"tags":"mensuration,similar-shapes,scaling","subtopic":"similar solids","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.733Z'::timestamptz, '2026-07-26T14:06:34.733Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0f1-7eb2-8663-cafb16ce1472'::uuid, '019f9df7-a2a2-7888-aef2-fd58477eb864'::uuid, 'The universal set is the integers from 0 to 10. Set A = {1, 4, 9} and set B = {1, 2, 4, 8}. Describe the elements of set A.', 'Perfect squares', 'The elements 1, 4 and 9 are the perfect squares in the universal set from 0 to 10.', 'Easy', '{"tags":"sets,perfect-squares","subtopic":"set description","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.737Z'::timestamptz, '2026-07-26T14:06:34.737Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0f5-75c8-9b42-505c50871466'::uuid, '019f9df7-a2a2-7888-aef2-fd58477eb864'::uuid, 'Find the number of elements in A ∪ B, where A = {1, 4, 9} and B = {1, 2, 4, 8}.', '5', 'A ∪ B = {1, 2, 4, 8, 9}. There are 5 elements in the union.', 'Easy', '{"tags":"sets,union,number-of-elements","subtopic":"union of sets","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.741Z'::timestamptz, '2026-07-26T14:06:34.741Z'::timestamptz) ON CONFLICT (id) DO NOTHING;